<?php
/**
 * deploy_all_8.php - Apollo Seikotsuin 8-Page & Assets Deployment Script
 * Brand: Orange & Yellow
 */
error_reporting(E_ALL);
ini_set('display_errors', 1);

$targetDir = __DIR__;
$files = [
    'index.html' => '',
    'menu.html' => '',
    'staff.html' => '',
    'photo.html' => '',
    'gallery.html' => '',
    'blog.html' => '',
    'review.html' => '',
    'access.html' => '',
    'map.html' => '',
    'accident.html' => '',
    'coupon.html' => '',
    'theme.css' => '',
    'images/a.png' => '',
    'images/aqua_tizer.jpg' => '',
    'images/DSC06554.JPG' => '',
    'images/DSC06568.JPG' => '',
    'images/line_bosyu.jpg' => '',
    'images/line_qr.jpg' => '',
    'images/logo.png' => '',
    'images/logo_old.png' => '',
    'images/main_visual.jpg' => '',
    'images/staff_ueno.jpg' => '',
    'images/sub1.jpg' => '',
    'images/sub2.jpg' => '',
    'images/sub3.jpg' => '',
];

echo "<h1>Deployment: Apollo Seikotsuin</h1>";
echo "<ul>";

foreach ($files as $filename => $base64Content) {
    $targetPath = $targetDir . '/' . $filename;
    $dir = dirname($targetPath);
    if (!is_dir($dir)) {
        mkdir($dir, 0755, true);
    }
    
    // Backup existing HTML/CSS if exists
    if (file_exists($targetPath) && strpos($filename, '/') === false) {
        $backupPath = $targetDir . '/backup_' . $filename . '_' . date('Ymd_His');
        copy($targetPath, $backupPath);
    }
    
    // Write new content
    if (file_put_contents($targetPath, base64_decode($base64Content)) !== false) {
        echo "<li>✅ Updated: <strong>$filename</strong></li>";
    } else {
        echo "<li>❌ Error: Failed to write $filename</li>";
    }
}

// Cleanup legacy admin.html if present
if (file_exists($targetDir . '/admin.html')) {
    unlink($targetDir . '/admin.html');
    echo "<li>⚠️ Deleted legacy admin.html to enforce Pages admin.</li>";
}

// Cleanup index.php if present
if (file_exists($targetDir . '/index.php')) {
    unlink($targetDir . '/index.php');
    echo "<li>⚠️ Deleted index.php to prevent routing conflict.</li>";
}

echo "</ul>";
echo "<p><strong>Success!</strong> All pages, theme.css, and images have been updated.</p>";
echo '<p><a href="index.html" style="font-size: 20px; font-weight: bold; color: #F39800;">サイトを確認する</a></p>';
?>